import React from "react";
import { Link } from "react-router-dom";
import "../App.css";

export default function ListingCard({ listing }) {
  // 🧩 Safety check — ensures listing exists and has a valid MongoDB ObjectId
  if (!listing || !listing._id || listing._id.length !== 24) {
    console.warn("⚠️ Skipping invalid listing:", listing);
    return null; // don’t render broken cards
  }

  return (
    <div className="listing-card">
      {/* Image */}
      <div className="listing-image">
        <img
          src={
            listing.image
              ? `http://localhost:5000/uploads/${listing.image}`
              : "/placeholder.png"
          }
          alt={listing.title}
        />
      </div>

      {/* Content */}
      <div className="listing-info">
        <h3 className="listing-title">{listing.title}</h3>
        <p className="listing-location">📍 {listing.location}</p>
        <p className="listing-price">💰 ₹{listing.price}</p>

        <div className="listing-meta">
          {listing.propertyType && <span>{listing.propertyType}</span>}
          {listing.purpose && (
            <span
              className={`listing-purpose ${
                listing.purpose === "Rent" ? "rent" : "sale"
              }`}
            >
              {listing.purpose}
            </span>
          )}
        </div>

        {/* Edit Button */}
        <Link to={`/edit-listing/${listing._id}`}>
          <button className="edit-btn">✏️ Edit</button>
        </Link>
      </div>
    </div>
  );
}
